# ! [doc = " Type metadata identifiers for LLVM Kernel Control Flow Integrity (KCFI) and cross-language LLVM"] # ! [doc = " KCFI support for the Rust compiler."] # ! [doc = ""] # ! [doc = " For more information about LLVM KCFI and cross-language LLVM KCFI support for the Rust compiler,"] # ! [doc = " see the tracking issue #123479."] use split_decls_genesis :: ourprelude :: * ; use std :: hash :: Hasher ; use rustc_middle :: ty :: { Instance , InstanceKind , ReifyReason , Ty , TyCtxt } ; use rustc_target :: callconv :: FnAbi ; use twox_hash :: XxHash64 ; pub use crate :: cfi :: typeid :: { TypeIdOptions , itanium_cxx_abi } ; #[doc = " Returns a KCFI type metadata identifier for the specified FnAbi."] pub fn typeid_for_fnabi < 'tcx > (tcx : TyCtxt < 'tcx > , fn_abi : & FnAbi < 'tcx , Ty < 'tcx > > , options : TypeIdOptions ,) -> u32 { let mut hash : XxHash64 = Default :: default () ; hash . write (itanium_cxx_abi :: typeid_for_fnabi (tcx , fn_abi , options) . as_bytes ()) ; hash . finish () as u32 } #[doc = " Returns a KCFI type metadata identifier for the specified Instance."] pub fn typeid_for_instance < 'tcx > (tcx : TyCtxt < 'tcx > , instance : Instance < 'tcx > , mut options : TypeIdOptions ,) -> u32 { if matches ! (instance . def , InstanceKind :: ReifyShim (_ , Some (ReifyReason :: FnPtr))) { options . insert (TypeIdOptions :: USE_CONCRETE_SELF) ; } let mut hash : XxHash64 = Default :: default () ; hash . write (itanium_cxx_abi :: typeid_for_instance (tcx , instance , options) . as_bytes ()) ; hash . finish () as u32 }